62	    private String customerCode;
63	
64	    @Column(name = "household_id")
65	    private String householdId;
66	
67	    @Column(name = "namesake_count")
68	    private Integer namesakeCount;
69	
70	    @Column(name = "household_size")
71	    private Integer householdSize;
72	
73	    @Column(name = "membership_number")
74	    private String membershipNumber;
75	
76	    @Column(name = "bulk_signup_warning", nullable = false)
77	    private boolean bulkSignupWarning;
78	
79	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
80	    private Set<Pet> pets;
81	
82	    public String getAddress() {
83	        return this.address;
84	    }
85	
86	    public void setAddress(String address) {
87	        this.address = address;
88	    }
89	
90	    public String getCity() {
91	        return this.city;
92	    }
93	
