103	        this.telephone = telephone;
104	    }
105	
106	    public String getEmail() {
107	        return this.email;
108	    }
109	
110	    public void setEmail(String email) {
111	        this.email = email;
112	    }
113	
114	    /**
115	     * The owner's postcode: a 4-digit code that, when supplied at creation, is validated
116	     * against the city's region and then stored verbatim. Optional, so may be null.
117	     */
118	    public String getPostcode() {
119	        return this.postcode;
120	    }
121	
122	    public void setPostcode(String postcode) {
123	        this.postcode = postcode;
124	    }
125	
126	    public LocalDate getRegistrationDate() {
127	        return this.registrationDate;
128	    }
129	
130	    public void setRegistrationDate(LocalDate registrationDate) {
131	        this.registrationDate = registrationDate;
132	    }
133	
134	    public String getCustomerCode() {
135	        return this.customerCode;
136	    }
137	
138	    public void setCustomerCode(String customerCode) {
139	        this.customerCode = customerCode;
140	    }
141	
142	    public String getHouseholdId() {
143	        return this.householdId;
144	    }
145	
146	    public void setHouseholdId(String householdId) {
147	        this.householdId = householdId;
148	    }
149	
150	    public Integer getNamesakeCount() {
151	        return this.namesakeCount;
152	    }
153	
154	    public void setNamesakeCount(Integer namesakeCount) {
155	        this.namesakeCount = namesakeCount;
156	    }
157	
158	    public Integer getHouseholdSize() {
159	        return this.householdSize;
160	    }
161	
162	    public void setHouseholdSize(Integer householdSize) {
163	        this.householdSize = householdSize;
164	    }
165	
166	    public String getMembershipNumber() {
167	        return this.membershipNumber;
168	    }
169	
170	    public void setMembershipNumber(String membershipNumber) {
171	        this.membershipNumber = membershipNumber;
172	    }
173	
174	    /**
175	     * Whether this owner was created as part of a bulk signup: {@code true} when more
176	     * than 80 owners had already been registered on this owner's registration date at
177	     * the moment it was created, {@code false} otherwise. Captured at creation.
178	     */
179	    public boolean isBulkSignupWarning() {
180	        return this.bulkSignupWarning;
181	    }
182	
183	    public void setBulkSignupWarning(boolean bulkSignupWarning) {
184	        this.bulkSignupWarning = bulkSignupWarning;
185	    }
186	
187	    /**
188	     * The owner's locality: the canonical region derived by preferring the postcode
189	     * range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099), falling back to the fixed
190	     * city-to-region table (Sydney->NSW, Melbourne->VIC, Brisbane->QLD) when the
191	     * postcode is absent or in no known range, or {@code "UNKNOWN"} otherwise. Derived
192	     * from stored state, never persisted.
193	     */
194	    public String getLocality() {
195	        return CityLocality.forPostcodeOrCity(this.postcode, this.city);
196	    }
197	
198	    /**
199	     * The owner's membership level, from 1 to 3: starts at 1, gains 1 when this owner has
200	     * an email address, and gains 1 when this owner had no namesakes at creation
201	     * ({@code namesakeCount} is 0). Capped at 3 (level 4 is reserved for tenure). Derived
202	     * from stored state, never persisted.
203	     */
204	    public int getMembershipLevel() {
205	        int level = 1;
206	        if (hasEmail()) {
207	            level++;
208	        }
209	        if (Integer.valueOf(0).equals(this.namesakeCount)) {
210	            level++;
211	        }
212	        return Math.min(level, 3);
213	    }
214	
215	    /**
216	     * The owner's preferred contact channel: {@code "EMAIL"} when an email address is
217	     * present, otherwise {@code "PHONE"}. Derived from stored state, never persisted.
218	     */
219	    public String getContactPreference() {
220	        return hasEmail() ? "EMAIL" : "PHONE";
221	    }
222	
223	    /**
224	     * The owner's identity key: the single value all duplicate detection is expressed
225	     * through, formed as the normalized telephone, the email (or empty when absent) and
226	     * the household id (or empty when none), joined by {@code '|'}. Two owners are
227	     * duplicates only when their whole identity keys are equal, so members of the same
228	     * household with different telephones have different keys and are all allowed. Derived
229	     * from stored state, never persisted.
230	     */
231	    public String getIdentityKey() {
232	        String emailPart = hasEmail() ? this.email : "";
233	        String householdPart = this.householdId == null ? "" : this.householdId;
234	        return this.telephone + "|" + emailPart + "|" + householdPart;
235	    }
236	
237	    private boolean hasEmail() {
238	        return this.email != null && !this.email.isEmpty();
239	    }
240	
241	    protected Set<Pet> getPetsInternal() {
242	        if (this.pets == null) {
243	            this.pets = new HashSet<>();
244	        }
245	        return this.pets;
246	    }
247	
248	    protected void setPetsInternal(Set<Pet> pets) {
249	        this.pets = pets;
250	    }
251	
252	    public List<Pet> getPets() {
253	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
254	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
255	        return Collections.unmodifiableList(sortedPets);
256	    }
257	
258	    public void setPets(List<Pet> pets) {
259	        this.pets = new HashSet<>(pets);
260	    }
261	
262	    public void addPet(Pet pet) {
263	        getPetsInternal().add(pet);
264	        pet.setOwner(this);
265	    }
266	
267	    /**
268	     * Return the Pet with the given name, or null if none found for this Owner.
269	     *
270	     * @param name to test
271	     * @return true if pet name is already in use
272	     */
273	    public Pet getPet(String name) {
274	        return getPet(name, false);
275	    }
276	
277	    /**
278	     * Return the Pet with the given name, or null if none found for this Owner.
279	     *
280	     * @param name to test
281	     * @return true if pet name is already in use
282	     */
283	    public Pet getPet(String name, boolean ignoreNew) {
284	        name = name.toLowerCase();
285	        for (Pet pet : getPetsInternal()) {
286	            if (!ignoreNew || !pet.isNew()) {
287	                String compName = pet.getName();
288	                compName = compName.toLowerCase();
289	                if (compName.equals(name)) {
290	                    return pet;
291	                }
292	            }
293	        }
294	        return null;
295	    }
296	
297	    public Pet getPet(Integer petId) {
298	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
299	    }
300	
301	    @Override
302	    public String toString() {
303	        return new ToStringCreator(this)
304	
305	            .append("id", this.getId())
306	            .append("new", this.isNew())
307	            .append("lastName", this.getLastName())
308	            .append("firstName", this.getFirstName())
309	            .append("address", this.address)
310	            .append("city", this.city)
311	            .append("telephone", this.telephone)
312	            .toString();
313	    }
314	}
