1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import org.slf4j.Logger;
4	import org.slf4j.LoggerFactory;
5	
6	import net.officefloor.plugin.variable.Val;
7	import org.springframework.samples.petclinic.model.Owner;
8	
9	/**
10	 * Emits an audit record for a successfully created owner to the dedicated {@code AUDIT}
11	 * logger, carrying the persisted owner id, its {@code customerCode}, its
12	 * {@code registrationDate} and its {@code membershipLevel}. Runs after {@link SaveOwner}
13	 * (so the generated id exists) and before {@link RespondWithOwnerCreated} responds.
14	 */
15	public class AuditOwnerCreated {
16	
17	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
18	
19	    public void service(@Val Owner owner) {
20	        AUDIT.info("Owner created id={} customerCode={} registrationDate={} membershipLevel={}",
21	                owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
22	                owner.getMembershipLevel());
23	    }
24	}
